-- VoteWars complete database schema snapshot. Run against Supabase Postgres.
CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;
CREATE TABLE IF NOT EXISTS public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,email text,predict_it_attempts int DEFAULT 0,predict_it_correct int DEFAULT 0,total_votes_cast int DEFAULT 0,total_topics_created int DEFAULT 0,total_options_created int DEFAULT 0,total_winning_options int DEFAULT 0,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.topics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,type text NOT NULL CHECK(type IN('predict_it','judge_it','settle_this','rank_it')),status text DEFAULT 'pending' CHECK(status IN('pending','active','resolved')),total_votes int DEFAULT 0,expires_at timestamptz,resolved_at timestamptz,created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic_id uuid NOT NULL REFERENCES public.topics(id) ON DELETE CASCADE,text text NOT NULL,vote_count int DEFAULT 0,delete_votes int DEFAULT 0,created_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,created_at timestamptz DEFAULT now());
ALTER TABLE public.topics ADD COLUMN IF NOT EXISTS correct_option_id uuid REFERENCES public.options(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS public.votes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic_id uuid NOT NULL REFERENCES public.topics(id) ON DELETE CASCADE,option_id uuid NOT NULL REFERENCES public.options(id) ON DELETE CASCADE,fingerprint text NOT NULL,user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,created_at timestamptz DEFAULT now(),UNIQUE(topic_id,fingerprint));
CREATE TABLE IF NOT EXISTS public.delete_votes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic_id uuid NOT NULL REFERENCES public.topics(id) ON DELETE CASCADE,option_id uuid NOT NULL REFERENCES public.options(id) ON DELETE CASCADE,fingerprint text NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(option_id,fingerprint));
CREATE TABLE IF NOT EXISTS public.brand_cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,tagline text,logo_url text,position int CHECK(position BETWEEN 1 AND 20),status text DEFAULT 'pending' CHECK(status IN('pending','active','resolved')),cook_votes int DEFAULT 0,roast_votes int DEFAULT 0,expires_at timestamptz,resolved_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.brand_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,tagline text,logo_url text,contact text,message text,status text DEFAULT 'pending',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.rate_limits(fingerprint text NOT NULL,endpoint text NOT NULL,request_count int DEFAULT 1,window_start timestamptz DEFAULT now(),PRIMARY KEY(fingerprint,endpoint));
CREATE TABLE IF NOT EXISTS public.brand_votes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),brand_id uuid NOT NULL REFERENCES public.brand_cards(id) ON DELETE CASCADE,fingerprint text NOT NULL,choice text NOT NULL CHECK(choice IN('cook','roast')),created_at timestamptz DEFAULT now(),UNIQUE(brand_id,fingerprint));
CREATE INDEX IF NOT EXISTS topics_feed_status_idx ON public.topics(status,created_at DESC);
CREATE INDEX IF NOT EXISTS options_topic_votes_idx ON public.options(topic_id,vote_count DESC);
CREATE INDEX IF NOT EXISTS votes_recent_topic_idx ON public.votes(topic_id,created_at DESC);
CREATE INDEX IF NOT EXISTS brand_cards_active_position_idx ON public.brand_cards(status,position ASC);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.topics ENABLE ROW LEVEL SECURITY; ALTER TABLE public.options ENABLE ROW LEVEL SECURITY; ALTER TABLE public.votes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.delete_votes ENABLE ROW LEVEL SECURITY; ALTER TABLE public.brand_cards ENABLE ROW LEVEL SECURITY; ALTER TABLE public.brand_applications ENABLE ROW LEVEL SECURITY; ALTER TABLE public.rate_limits ENABLE ROW LEVEL SECURITY; ALTER TABLE public.brand_votes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS profiles_select_own ON public.profiles; CREATE POLICY profiles_select_own ON public.profiles FOR SELECT TO authenticated USING(auth.uid()=id);
DROP POLICY IF EXISTS profiles_update_own ON public.profiles; CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING(auth.uid()=id) WITH CHECK(auth.uid()=id);
DROP POLICY IF EXISTS topics_public_read ON public.topics; CREATE POLICY topics_public_read ON public.topics FOR SELECT TO anon,authenticated USING(status IN('active','resolved'));
DROP POLICY IF EXISTS topics_auth_insert ON public.topics; CREATE POLICY topics_auth_insert ON public.topics FOR INSERT TO authenticated WITH CHECK(true);
DROP POLICY IF EXISTS options_public_read ON public.options; CREATE POLICY options_public_read ON public.options FOR SELECT TO anon,authenticated USING(true);
DROP POLICY IF EXISTS options_auth_insert ON public.options; CREATE POLICY options_auth_insert ON public.options FOR INSERT TO authenticated WITH CHECK(true);
DROP POLICY IF EXISTS brand_cards_public_read ON public.brand_cards; CREATE POLICY brand_cards_public_read ON public.brand_cards FOR SELECT TO anon,authenticated USING(status='active');
DROP POLICY IF EXISTS brand_applications_public_insert ON public.brand_applications; CREATE POLICY brand_applications_public_insert ON public.brand_applications FOR INSERT TO anon,authenticated WITH CHECK(true);
DROP POLICY IF EXISTS brand_votes_service_only ON public.brand_votes; CREATE POLICY brand_votes_service_only ON public.brand_votes FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger AS $$ BEGIN INSERT INTO public.profiles(id,email) VALUES(NEW.id,NEW.email); RETURN NEW; END; $$ LANGUAGE plpgsql SECURITY DEFINER SET search_path=public;
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users; CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE OR REPLACE FUNCTION public.guard_topic_option_cap() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN PERFORM 1 FROM public.topics WHERE id=NEW.topic_id FOR UPDATE; SELECT count(*) INTO n FROM public.options WHERE topic_id=NEW.topic_id; IF n>=5 THEN RAISE EXCEPTION 'This topic is full. Max 5 options.'; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS enforce_topic_option_cap ON public.options; CREATE TRIGGER enforce_topic_option_cap BEFORE INSERT ON public.options FOR EACH ROW EXECUTE FUNCTION public.guard_topic_option_cap();
CREATE OR REPLACE FUNCTION public.consume_rate_limit(p_fingerprint text,p_endpoint text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.rate_limits(fingerprint,endpoint,request_count,window_start) VALUES(p_fingerprint,p_endpoint,1,now()) ON CONFLICT(fingerprint,endpoint) DO UPDATE SET request_count=CASE WHEN rate_limits.window_start<now()-interval '60 seconds' THEN 1 ELSE rate_limits.request_count+1 END,window_start=CASE WHEN rate_limits.window_start<now()-interval '60 seconds' THEN now() ELSE rate_limits.window_start END RETURNING request_count INTO n; RETURN n; END; $$;
REVOKE ALL ON FUNCTION public.consume_rate_limit(text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.consume_rate_limit(text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.cast_topic_vote(p_topic uuid,p_option uuid,p_fingerprint text,p_user uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ins uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.topics WHERE id=p_topic AND status='active') THEN RAISE EXCEPTION 'Topic is not active'; END IF; IF NOT EXISTS(SELECT 1 FROM public.options WHERE id=p_option AND topic_id=p_topic) THEN RAISE EXCEPTION 'Invalid option'; END IF; INSERT INTO public.votes(topic_id,option_id,fingerprint,user_id) VALUES(p_topic,p_option,p_fingerprint,p_user) ON CONFLICT(topic_id,fingerprint) DO NOTHING RETURNING id INTO ins; IF ins IS NULL THEN RAISE EXCEPTION 'You have already voted on this topic'; END IF; UPDATE public.options SET vote_count=vote_count+1 WHERE id=p_option; UPDATE public.topics SET total_votes=total_votes+1 WHERE id=p_topic; IF p_user IS NOT NULL THEN UPDATE public.profiles SET total_votes_cast=total_votes_cast+1 WHERE id=p_user; END IF; RETURN jsonb_build_object('ok',true); END; $$;
CREATE OR REPLACE FUNCTION public.cast_option_delete_vote(p_topic uuid,p_option uuid,p_fingerprint text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ins uuid; pressure numeric; vt integer; oc timestamptz; removed boolean:=false; BEGIN IF NOT EXISTS(SELECT 1 FROM public.topics WHERE id=p_topic AND status='active') THEN RAISE EXCEPTION 'Topic is not active'; END IF; SELECT created_at INTO oc FROM public.options WHERE id=p_option AND topic_id=p_topic FOR UPDATE; IF oc IS NULL THEN RAISE EXCEPTION 'Option not found'; END IF; IF oc>now()-interval '1 hour' THEN RAISE EXCEPTION 'Options cannot be removed during their first hour'; END IF; INSERT INTO public.delete_votes(topic_id,option_id,fingerprint) VALUES(p_topic,p_option,p_fingerprint) ON CONFLICT(option_id,fingerprint) DO NOTHING RETURNING id INTO ins; IF ins IS NULL THEN RAISE EXCEPTION 'Already voted to remove this option'; END IF; UPDATE public.options SET delete_votes=delete_votes+1 WHERE id=p_option; SELECT total_votes INTO vt FROM public.topics WHERE id=p_topic FOR UPDATE; SELECT delete_votes::numeric/GREATEST(vt,1) INTO pressure FROM public.options WHERE id=p_option; IF pressure>=.30 THEN UPDATE public.topics SET total_votes=GREATEST(0,total_votes-(SELECT vote_count FROM public.options WHERE id=p_option)) WHERE id=p_topic; DELETE FROM public.options WHERE id=p_option; removed:=true; END IF; RETURN jsonb_build_object('ok',true,'removed',removed); END; $$;
CREATE OR REPLACE FUNCTION public.cast_brand_vote(p_brand uuid,p_fingerprint text,p_choice text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ins uuid; BEGIN IF p_choice NOT IN('cook','roast') THEN RAISE EXCEPTION 'Invalid choice'; END IF; IF NOT EXISTS(SELECT 1 FROM public.brand_cards WHERE id=p_brand AND status='active') THEN RAISE EXCEPTION 'Brand is not active'; END IF; INSERT INTO public.brand_votes(brand_id,fingerprint,choice) VALUES(p_brand,p_fingerprint,p_choice) ON CONFLICT(brand_id,fingerprint) DO NOTHING RETURNING id INTO ins; IF ins IS NULL THEN RAISE EXCEPTION 'Already voted on this brand'; END IF; IF p_choice='cook' THEN UPDATE public.brand_cards SET cook_votes=cook_votes+1 WHERE id=p_brand; ELSE UPDATE public.brand_cards SET roast_votes=roast_votes+1 WHERE id=p_brand; END IF; RETURN jsonb_build_object('ok',true); END; $$;
GRANT EXECUTE ON FUNCTION public.cast_topic_vote(uuid,uuid,text,uuid),public.cast_option_delete_vote(uuid,uuid,text),public.cast_brand_vote(uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.increment_profile_stat(p_user uuid,p_column text,p_delta integer DEFAULT 1) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_column NOT IN('total_topics_created','total_options_created') OR p_delta<0 THEN RAISE EXCEPTION 'Invalid profile stat'; END IF; EXECUTE format('UPDATE public.profiles SET %I=%I+$2 WHERE id=$1',p_column,p_column) USING p_user,p_delta; END; $$; GRANT EXECUTE ON FUNCTION public.increment_profile_stat(uuid,text,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.resolve_expired_topics() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t record; m integer; BEGIN FOR t IN SELECT id FROM public.topics WHERE status='active' AND expires_at<=now() FOR UPDATE LOOP SELECT max(vote_count) INTO m FROM public.options WHERE topic_id=t.id; IF m IS NOT NULL THEN UPDATE public.profiles p SET total_winning_options=p.total_winning_options+x.n FROM(SELECT created_by,count(*)::integer n FROM public.options WHERE topic_id=t.id AND vote_count=m AND created_by IS NOT NULL GROUP BY created_by)x WHERE p.id=x.created_by; END IF; UPDATE public.topics SET status='resolved',resolved_at=now() WHERE id=t.id; END LOOP; END; $$;
CREATE OR REPLACE FUNCTION public.approve_brand_application(p_application uuid,p_position integer,p_duration_hours integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.brand_applications%ROWTYPE; ni uuid; BEGIN IF p_position<1 OR p_position>20 OR p_duration_hours NOT IN(24,48,72,168) THEN RAISE EXCEPTION 'Invalid position or duration'; END IF; LOCK TABLE public.brand_cards IN EXCLUSIVE MODE; SELECT * INTO a FROM public.brand_applications WHERE id=p_application AND status='pending' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Pending application not found'; END IF; IF(SELECT count(*) FROM public.brand_cards WHERE status='active')>=20 THEN RAISE EXCEPTION 'Maximum of 20 active brands reached'; END IF; IF EXISTS(SELECT 1 FROM public.brand_cards WHERE status='active' AND position>=p_position AND position=20) THEN RAISE EXCEPTION 'No room to shift brands at this position'; END IF; UPDATE public.brand_cards SET position=position+1 WHERE status='active' AND position>=p_position; INSERT INTO public.brand_cards(name,tagline,logo_url,position,status,expires_at) VALUES(a.name,a.tagline,a.logo_url,p_position,'active',now()+make_interval(hours=>p_duration_hours)) RETURNING id INTO ni; UPDATE public.brand_applications SET status='approved' WHERE id=p_application; RETURN ni; END; $$;
CREATE OR REPLACE FUNCTION public.delete_active_brand(p_brand uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pos integer; BEGIN LOCK TABLE public.brand_cards IN EXCLUSIVE MODE; SELECT position INTO pos FROM public.brand_cards WHERE id=p_brand AND status='active' FOR UPDATE; IF pos IS NULL THEN RAISE EXCEPTION 'Active brand not found'; END IF; DELETE FROM public.brand_cards WHERE id=p_brand; UPDATE public.brand_cards SET position=position-1 WHERE status='active' AND position>pos; END; $$;
CREATE OR REPLACE FUNCTION public.admin_dashboard_metrics() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH prior AS(SELECT DISTINCT fingerprint FROM public.votes WHERE created_at::date=CURRENT_DATE-1),today AS(SELECT DISTINCT fingerprint FROM public.votes WHERE created_at::date=CURRENT_DATE) SELECT jsonb_build_object('active_topics',(SELECT count(*) FROM public.topics WHERE status='active'),'votes_today',(SELECT count(*) FROM public.votes WHERE created_at::date=CURRENT_DATE),'day2_return_rate',CASE WHEN(SELECT count(*) FROM prior)=0 THEN 0 ELSE round((SELECT count(*) FROM prior p WHERE EXISTS(SELECT 1 FROM today t WHERE t.fingerprint=p.fingerprint))*100.0/(SELECT count(*) FROM prior),1) END,'active_brands',(SELECT count(*) FROM public.brand_cards WHERE status='active'),'brand_votes_today',(SELECT count(*) FROM public.brand_votes WHERE created_at::date=CURRENT_DATE)) $$;
REVOKE ALL ON FUNCTION public.approve_brand_application(uuid,integer,integer),public.delete_active_brand(uuid),public.admin_dashboard_metrics() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.approve_brand_application(uuid,integer,integer),public.delete_active_brand(uuid),public.admin_dashboard_metrics() TO service_role;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='options') THEN ALTER PUBLICATION supabase_realtime ADD TABLE public.options; END IF; END $$;
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types) VALUES('brand-logos','brand-logos',true,5242880,ARRAY['image/png','image/jpeg','image/webp','image/svg+xml']) ON CONFLICT(id) DO NOTHING;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='resolve-topics') THEN PERFORM cron.schedule('resolve-topics','0 0 * * *','SELECT public.resolve_expired_topics()'); END IF; IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='delete-topics') THEN PERFORM cron.schedule('delete-topics','0 0 * * *',$q$DELETE FROM public.topics WHERE status='resolved' AND resolved_at < NOW()-INTERVAL '7 days'$q$); END IF; IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='resolve-brands') THEN PERFORM cron.schedule('resolve-brands','0 0 * * *',$q$UPDATE public.brand_cards SET status='resolved',resolved_at=NOW() WHERE status='active' AND expires_at<=NOW()$q$); END IF; IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='delete-brands') THEN PERFORM cron.schedule('delete-brands','0 0 * * *',$q$DELETE FROM public.brand_cards WHERE status='resolved' AND resolved_at<NOW()-INTERVAL '7 days'$q$); END IF; END $$;
CREATE OR REPLACE FUNCTION public.admin_moderate_topic(p_topic uuid,p_action text,p_duration_hours integer DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF p_action='approve' THEN IF p_duration_hours NOT IN(24,48,72,168) THEN RAISE EXCEPTION 'Invalid duration'; END IF; UPDATE public.topics SET status='active',expires_at=now()+make_interval(hours=>p_duration_hours) WHERE id=p_topic AND status='pending'; ELSIF p_action='reject' THEN DELETE FROM public.topics WHERE id=p_topic AND status='pending'; ELSIF p_action='resolve' THEN UPDATE public.topics SET status='resolved',resolved_at=now() WHERE id=p_topic AND status='active'; ELSIF p_action='delete' THEN DELETE FROM public.topics WHERE id=p_topic; ELSE RAISE EXCEPTION 'Invalid action'; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'Topic not found or state changed'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.cast_topic_vote(uuid,uuid,text,uuid),public.cast_option_delete_vote(uuid,uuid,text),public.cast_brand_vote(uuid,text,text),public.increment_profile_stat(uuid,text,integer),public.resolve_expired_topics(),public.admin_moderate_topic(uuid,text,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cast_topic_vote(uuid,uuid,text,uuid),public.cast_option_delete_vote(uuid,uuid,text),public.cast_brand_vote(uuid,text,text),public.increment_profile_stat(uuid,text,integer),public.resolve_expired_topics(),public.admin_moderate_topic(uuid,text,integer) TO service_role;
